# Extract the questions (lines with "Date:" and "Instance:")
import re

lines = context.split('\n')
questions = []
for line in lines:
    if 'Date:' in line and 'Instance:' in line:
        # Extract the instance part
        match = re.search(r'Instance: (.+?)$', line)
        if match:
            questions.append(match.group(1))

print(f"Found {len(questions)} questions:")
for i, q in enumerate(questions, 1):
    print(f"{i}. {q[:100]}...")
